python3 -c '
import os, time

files_with_mtime = []
for root, dirs, files in os.walk("/workspace"):
    if "/results/" in root or "/models/" in root or "/data/" in root or "__pycache__" in root or ".egg-info" in root:
        continue
    for f in files:
        p = os.path.join(root, f)
        try:
            st = os.stat(p)
            files_with_mtime.append((st.st_mtime, p))
        except:
            pass

files_with_mtime.sort(reverse=True)
for mtime, p in files_with_mtime[:40]:
    print(f"{time.strftime(\"%Y-%m-%d %H:%M:%S\", time.localtime(mtime))}  {p}")
'

